def def_norm_text(x):
    s = str(x or "").replace("\u3000", " ").lower()
    s = s.replace("&", "and")
    s = re.sub(r"[^a-z0-9\u4e00-\u9fff/%]+", " ", s)
    return re.sub(r"\s+", " ", s).strip()

def def_get_financial_account_ssot_v05912():
    return VRN_FINANCIAL_ACCOUNT_SSOT_V05912

def def_match_financial_account_v05912(text):
    nr = def_norm_text(text)
    for acc in VRN_FINANCIAL_ACCOUNT_SSOT_V05912.get("accounts", []):
        for k in [acc.get("canonical", "")] + acc.get("aliases", []):
            if def_norm_text(k) == nr:
                return {
                    "matched": True,
                    "account": acc.get("canonical", ""),
                    "category": acc.get("category", ""),
                    "unit": acc.get("unit", ""),
                    "match_score": 100,
                    "match_reason": "exact alias"
                }
    return {
        "matched": False,
        "account": str(text or ""),
        "category": "Unmapped",
        "unit": "",
        "match_score": 0,
        "match_reason": "not found"
    }
